-- READ-ONLY drift check for 20270430-0432 (staging section 2b, step V0): fingerprints of the 19 functions/views they replace
-- + the two new columns. Before 0430 the output must equal visit-confirmation-fingerprints-pre.txt (the state 0430-0432 were
-- tested on); after 0432 it must equal visit-confirmation-fingerprints-with.txt.
select n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||') '||md5(pg_get_functiondef(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname||'.'||p.proname in ('private.keep_offer_evidence','public._ai_auto_respond_to_business_requests','public._business_request_fanout','public._match_request_to_availability_core','public._match_request_to_policy_core','public.admin_business_offer_history','public.complete_business_reservation','public.get_business_opportunities','public.get_market_validation_stats','public.get_marketplace_reliability_rankings','public.get_partner_category_outcomes','public.get_partner_offer_funnel','public.get_partner_offer_performance','public.get_partner_offer_reputation','public.get_partner_offer_value','public.intent_funnel','public.mark_business_no_show','public.request_journey','public.routing_candidate_outcomes')
union all
select n.nspname||'.'||c.relname||' view '||md5(pg_get_viewdef(c.oid)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in ('v','m') and n.nspname||'.'||c.relname in ('private.keep_offer_evidence','public._ai_auto_respond_to_business_requests','public._business_request_fanout','public._match_request_to_availability_core','public._match_request_to_policy_core','public.admin_business_offer_history','public.complete_business_reservation','public.get_business_opportunities','public.get_market_validation_stats','public.get_marketplace_reliability_rankings','public.get_partner_category_outcomes','public.get_partner_offer_funnel','public.get_partner_offer_performance','public.get_partner_offer_reputation','public.get_partner_offer_value','public.intent_funnel','public.mark_business_no_show','public.request_journey','public.routing_candidate_outcomes')
union all
select 'col business_request_offers.'||column_name from information_schema.columns where table_schema='public' and table_name='business_request_offers' and column_name in ('customer_done_at','visit_confirmed_at')
order by 1;
